let failCount = 0;
const testResults = [];

function recordResult(id, title, passed, durationMs, details, error) {
  testCount++;
  if (passed) {
    passCount++;
    console.log('  [' + id + '] ' + title + ' ... ' + C.green + '✔ PASS' + C.reset + ' ' + C.gray + '(' + durationMs + 'ms)' + C.reset);
  } else {
    failCount++;
    console.log('  [' + id + '] ' + title + ' ... ' + C.red + '✖ FAIL' + C.reset + ' ' + C.gray + '(' + durationMs + 'ms)' + C.reset);
    if (error) {
      console.log('      ' + C.red + 'Error: ' + (error.stack || error.message || error) + C.reset);
    }
  }
  if (details && (process.env.VERBOSE || !passed)) {
    console.log('      ' + C.gray + 'Details: ' + JSON.stringify(details) + C.reset);
  }
  testResults.push({ id: id, title: title, passed: passed, durationMs: durationMs, details: details, error: error ? error.message : null });
}

async function runTest(id, title, testFn) {
  const start = Date.now();
  try {
    const details = await testFn();
    const duration = Date.now() - start;
    recordResult(id, title, true, duration, details);
  } catch (err) {
    const duration = Date.now() - start;
    recordResult(id, title, false, duration, null, err);
  }
}

function assert(cond, msg) {
  if (!cond) throw new Error(msg || 'Assertion failed');
}

/**
 * Strip comments and string literals while preserving exact character indices and line numbers
 */
function stripCommentsAndStrings(src) {
  let out = '';
  let i = 0;
  const len = src.length;
  while (i < len) {
    if (src[i] === '/' && src[i + 1] === '/') {
      i += 2;
      out += '  ';
      while (i < len && src[i] !== '\n') {
        out += ' ';
        i++;
      }
    } else if (src[i] === '/' && src[i + 1] === '*') {
      i += 2;
      out += '  ';
      while (i < len && !(src[i] === '*' && src[i + 1] === '/')) {
        if (src[i] === '\n') out += '\n';
        else out += ' ';
        i++;
      }
      if (i < len) {
        i += 2;
        out += '  ';
      }
    } else if (src[i] === '"' || src[i] === "'") {
      const q = src[i++];
      out += ' ';
      while (i < len && src[i] !== q) {
        if (src[i] === '\\') {
          out += '  ';
          i += 2;
          continue;
        }
        if (src[i] === '\n') out += '\n';
        else out += ' ';
        i++;
      }
      if (i < len) {
        i++;
        out += ' ';
      }
    } else if (src[i] === '`') {
      i++;
      out += ' ';
      while (i < len && src[i] !== '`') {
        if (src[i] === '\\') {
          out += '  ';
          i += 2;
          continue;
        }
        if (src[i] === '\n') out += '\n';
        else out += ' ';
        i++;
      }
      if (i < len) {
        i++;
        out += ' ';
      }
    } else {
      out += src[i++];
    }
  }
  return out;
}

/**
 * AST Node Visitor for Acorn AST
 */
function walkAst(node, visitors) {
  if (!node || typeof node !== 'object') return;
  const type = node.type;
  if (visitors[type]) {
    visitors[type](node);
  }
  for (const key in node) {
    if (Object.prototype.hasOwnProperty.call(node, key)) {
      const child = node[key];
      if (Array.isArray(child)) {
        for (let i = 0; i < child.length; i++) {
          walkAst(child[i], visitors);
        }
      } else if (child && typeof child === 'object' && typeof child.type === 'string') {
        walkAst(child, visitors);
      }
    }
  }
}

