    assert(resp.pong === true, 'ping.pong must be true');
    assert(typeof resp.time === 'number' && resp.time > 0, 'ping.time must be timestamp');
    assert(resp.serviceId === 'com.cinejoy.tv.service', 'ping.serviceId mismatch');

    return { pingResponse: resp };
  });

  await runTest('S3.9', 'Luna interface resilience when activityManager is undefined/stripped', function () {
    const strippedMockService = createLunaServiceMock('com.cinejoy.tv.service');
    // Strip activityManager
    delete strippedMockService.activityManager;

    // Verify registering methods does not crash if activityManager is undefined
    let crashed = false;
    try {
      if (strippedMockService.activityManager) {
        strippedMockService.activityManager.exitOnTimeout = false;
      }
      strippedMockService.register('keepalive', function (m) { m.respond({ returnValue: true }); });
    } catch (_) {
      crashed = true;
    }
    assert(!crashed, 'Failed graceful degradation when activityManager is missing');

    return { survivedActivityManagerAbsence: true };
  });

  // =========================================================================
  // SUMMARY AND VERDICT
  // =========================================================================
  console.log('\n' + C.bold + '► Challenger Verification Summary' + C.reset);
  console.log('------------------------------------------------------------------------');
  console.log('  Total Checks Run: ' + testCount);
  console.log('  Passed Checks:    ' + C.green + C.bold + passCount + C.reset);
  console.log('  Failed Checks:    ' + (failCount > 0 ? (C.red + C.bold + failCount + C.reset) : '0'));
  console.log('------------------------------------------------------------------------\n');

  if (failCount > 0) {
    console.error(C.red + C.bold + 'CHALLENGER VERDICT: FAIL — INCOMPATIBILITIES OR VULNERABILITIES DETECTED' + C.reset);
    process.exit(1);
  } else {
    console.log(C.green + C.bold + 'CHALLENGER VERDICT: ALL ' + testCount + ' EMPIRICAL CHECKS PASSED (100% EMPIRICAL SUCCESS)' + C.reset);
    process.exit(0);
  }
}

main().catch(function (err) {
  console.error('Fatal test error:', err);
  process.exit(1);
});

