/**
 * tests/adversarial-prod1-challenger-node12-luna.js
 *
 * Empirical Adversarial Challenger Test Suite:
 * Focus:
 *   1. Strict Node 12.22.2 runtime compatibility: AST and token scanning across all service files
 *      for any ES2020+ syntax (e.g. ?., ??, numeric separator _, BigInt literals, Promise.allSettled, fetch).
 *   2. Luna bus interface mock: keepalive subscription registration, cancellation, status reporting,
 *      and Triple-Shield persistence.
 *   3. Zero external npm dependencies rule in package.json and require() audits.
 *
 * Compatibility: Pure Node 12 through Node 26+ built-ins.
 */

'use strict';

const fs = require('fs');
const path = require('path');
const http = require('http');
const Module = require('module');

// ANSI Terminal Colors
const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  cyan: '\x1b[36m',
  gray: '\x1b[90m',
  magenta: '\x1b[35m'
};

const SERVICE_DIR = path.resolve(__dirname, '../services/com.cinejoy.tv.service');
const SERVICE_FILES = ['http-client.js', 'resolver.js', 'hls-proxy.js', 'index.js', 'test-service.js'];

// Load Acorn if available for full ES2019 AST parsing
let acorn = null;
const acornPaths = [
  '/home/prem/.local/share/nvim.bak/mason/packages/eslint_d/node_modules/eslint_d/node_modules/acorn/dist/acorn.js',
  'acorn'
];
for (let i = 0; i < acornPaths.length; i++) {
  try {
    acorn = require(acornPaths[i]);
    break;
  } catch (_) {}
}

let testCount = 0;
let passCount = 0;
let failCount = 0;
const testResults = [];

function recordResult(id, title, passed, durationMs, details, error) {
  testCount++;
  if (passed) {
    passCount++;
    console.log('  [' + id + '] ' + title + ' ... ' + C.green + '✔ PASS' + C.reset + ' ' + C.gray + '(' + durationMs + 'ms)' + C.reset);
  } else {
    failCount++;
    console.log('  [' + id + '] ' + title + ' ... ' + C.red + '✖ FAIL' + C.reset + ' ' + C.gray + '(' + durationMs + 'ms)' + C.reset);
    if (error) {
      console.log('      ' + C.red + 'Error: ' + (error.stack || error.message || error) + C.reset);
    }
  }
  if (details && (process.env.VERBOSE || !passed)) {
    console.log('      ' + C.gray + 'Details: ' + JSON.stringify(details) + C.reset);
  }
  testResults.push({ id: id, title: title, passed: passed, durationMs: durationMs, details: details, error: error ? error.message : null });
}

async function runTest(id, title, testFn) {
  const start = Date.now();
  try {
    const details = await testFn();
    const duration = Date.now() - start;
    recordResult(id, title, true, duration, details);
  } catch (err) {
    const duration = Date.now() - start;
    recordResult(id, title, false, duration, null, err);
  }
}

function assert(cond, msg) {
  if (!cond) throw new Error(msg || 'Assertion failed');
}

/**
 * Strip comments and string literals while preserving exact character indices and line numbers
 */
function stripCommentsAndStrings(src) {
  let out = '';
  let i = 0;
  const len = src.length;
  while (i < len) {
    if (src[i] === '/' && src[i + 1] === '/') {
      i += 2;
      out += '  ';
      while (i < len && src[i] !== '\n') {
        out += ' ';
        i++;
      }
    } else if (src[i] === '/' && src[i + 1] === '*') {
      i += 2;
      out += '  ';
      while (i < len && !(src[i] === '*' && src[i + 1] === '/')) {
        if (src[i] === '\n') out += '\n';
        else out += ' ';
        i++;
      }
      if (i < len) {
        i += 2;
        out += '  ';
      }
    } else if (src[i] === '"' || src[i] === "'") {
      const q = src[i++];
      out += ' ';
      while (i < len && src[i] !== q) {
        if (src[i] === '\\') {
          out += '  ';
          i += 2;
          continue;
        }
        if (src[i] === '\n') out += '\n';
        else out += ' ';
        i++;
      }
      if (i < len) {
        i++;
        out += ' ';
      }
    } else if (src[i] === '`') {
      i++;
      out += ' ';
      while (i < len && src[i] !== '`') {
        if (src[i] === '\\') {
          out += '  ';
          i += 2;
          continue;
        }
        if (src[i] === '\n') out += '\n';
        else out += ' ';
        i++;
      }
      if (i < len) {
        i++;
        out += ' ';
      }
    } else {
      out += src[i++];
    }
  }
  return out;
}

/**
 * AST Node Visitor for Acorn AST
 */
function walkAst(node, visitors) {
  if (!node || typeof node !== 'object') return;
  const type = node.type;
  if (visitors[type]) {
    visitors[type](node);
  }
  for (const key in node) {
    if (Object.prototype.hasOwnProperty.call(node, key)) {
      const child = node[key];
      if (Array.isArray(child)) {
        for (let i = 0; i < child.length; i++) {
          walkAst(child[i], visitors);
        }
      } else if (child && typeof child === 'object' && typeof child.type === 'string') {
        walkAst(child, visitors);
      }
    }
  }
}

async function main() {
  console.log('\n' + C.bold + C.magenta + '========================================================================' + C.reset);
  console.log(C.bold + C.magenta + '   CINEJOY ADVERSARIAL CHALLENGER SUITE: Node 12 & Luna Interface' + C.reset);
  console.log(C.bold + C.magenta + '========================================================================' + C.reset + '\n');
  console.log(C.bold + 'Target Service:' + C.reset + ' ' + SERVICE_DIR);
  console.log(C.bold + 'Host Runtime:  ' + C.reset + ' ' + process.version + ' on ' + process.platform + ' ' + process.arch);
  console.log(C.bold + 'Acorn Parser:  ' + C.reset + ' ' + (acorn ? ('v' + acorn.version) : 'Not available') + '\n');

  // =========================================================================
  // SUITE 1: STRICT NODE 12 RUNTIME COMPATIBILITY & AST/TOKEN SCANNING
  // =========================================================================
  console.log(C.bold + C.cyan + '--- SUITE 1: Strict Node 12 Compatibility & AST/Token Auditing ---' + C.reset);

  await runTest('S1.1', 'Acorn AST parse with ecmaVersion: 2019 (Strict ES2019/Node 12 baseline)', function () {
    assert(acorn, 'Acorn parser required for AST parse verification');
    const parseErrors = [];
    for (let f = 0; f < SERVICE_FILES.length; f++) {
      const filename = SERVICE_FILES[f];
      const filePath = path.join(SERVICE_DIR, filename);
      const code = fs.readFileSync(filePath, 'utf8');
      try {
        acorn.parse(code, {
          ecmaVersion: 2019,
          sourceType: 'script',
          locations: true
        });
      } catch (err) {
        parseErrors.push({ file: filename, error: err.message, loc: err.loc });
      }
    }
    assert(parseErrors.length === 0, 'Found files failing ES2019 parse: ' + JSON.stringify(parseErrors));
    return { filesChecked: SERVICE_FILES.length, parseErrors: 0, ecmaVersion: 2019 };
  });

  await runTest('S1.2', 'AST Walk: Negative verification against ES2020+ AST nodes', function () {
    assert(acorn, 'Acorn parser required for AST verification');
    const violations = [];

    for (let f = 0; f < SERVICE_FILES.length; f++) {
      const filename = SERVICE_FILES[f];
      const filePath = path.join(SERVICE_DIR, filename);
      const code = fs.readFileSync(filePath, 'utf8');
      const ast = acorn.parse(code, {
        ecmaVersion: 'latest',
        sourceType: 'script',
        locations: true
      });

      walkAst(ast, {
        ChainExpression: function (node) {
          violations.push({ file: filename, type: 'OptionalChaining (ChainExpression)', line: node.loc.start.line });
        },
        LogicalExpression: function (node) {
          if (node.operator === '??') {
            violations.push({ file: filename, type: 'NullishCoalescing (??)', line: node.loc.start.line });
          }
        },
        AssignmentExpression: function (node) {
          if (node.operator === '&&=' || node.operator === '||=' || node.operator === '??=') {
            violations.push({ file: filename, type: 'LogicalAssignment (' + node.operator + ')', line: node.loc.start.line });
          }
        },
        Literal: function (node) {
          if (node.bigint) {
            violations.push({ file: filename, type: 'BigIntLiteral (' + node.raw + ')', line: node.loc.start.line });
          }
          if (typeof node.value === 'number' && node.raw && node.raw.indexOf('_') !== -1) {
            violations.push({ file: filename, type: 'NumericSeparator (' + node.raw + ')', line: node.loc.start.line });
          }
        },
        ImportExpression: function (node) {
          violations.push({ file: filename, type: 'DynamicImport (import())', line: node.loc.start.line });
        },
        MetaProperty: function (node) {
          violations.push({ file: filename, type: 'MetaProperty (import.meta)', line: node.loc.start.line });
        }
      });
    }

    assert(violations.length === 0, 'Found prohibited ES2020+ AST nodes: ' + JSON.stringify(violations));
    return { filesChecked: SERVICE_FILES.length, violations: 0 };
  });

  await runTest('S1.3', 'AST Identifier Walk: Detection of forbidden Node 18+ runtime globals and APIs', function () {
    assert(acorn, 'Acorn parser required for AST walk');
    const forbiddenIdentifiers = ['fetch', 'AbortController', 'AbortSignal', 'ReadableStream', 'WritableStream', 'TransformStream', 'Blob', 'FormData', 'structuredClone'];
    const forbiddenMemberMethods = [
      { obj: 'Promise', prop: 'allSettled' },
      { obj: 'Promise', prop: 'any' },
      { obj: 'Readable', prop: 'fromWeb' },
      { obj: 'stream', prop: 'fromWeb' },
      { obj: 'crypto', prop: 'randomUUID' },
      { obj: 'Object', prop: 'hasOwn' }
    ];

    const violations = [];

    for (let f = 0; f < SERVICE_FILES.length; f++) {
      const filename = SERVICE_FILES[f];
      const filePath = path.join(SERVICE_DIR, filename);
      const code = fs.readFileSync(filePath, 'utf8');
      const ast = acorn.parse(code, {
        ecmaVersion: 'latest',
        sourceType: 'script',
        locations: true
      });

      const declaredIdentifiers = new Set();

      walkAst(ast, {
        VariableDeclarator: function (node) {
          if (node.id && node.id.name) declaredIdentifiers.add(node.id.name);
        },
        FunctionDeclaration: function (node) {
          if (node.id && node.id.name) declaredIdentifiers.add(node.id.name);
          if (Array.isArray(node.params)) {
            node.params.forEach(function (p) { if (p.name) declaredIdentifiers.add(p.name); });
          }
        },
        FunctionExpression: function (node) {
          if (Array.isArray(node.params)) {
            node.params.forEach(function (p) { if (p.name) declaredIdentifiers.add(p.name); });
          }
        },
        Identifier: function (node) {
          if (forbiddenIdentifiers.indexOf(node.name) !== -1) {
            if (!declaredIdentifiers.has(node.name)) {
              violations.push({ file: filename, global: node.name, line: node.loc.start.line });
            }
          }
        },
        MemberExpression: function (node) {
          const propName = node.property ? node.property.name : null;
          const objName = node.object ? node.object.name : null;
          for (let m = 0; m < forbiddenMemberMethods.length; m++) {
            const forbidden = forbiddenMemberMethods[m];
            if (objName === forbidden.obj && propName === forbidden.prop) {
              violations.push({ file: filename, member: objName + '.' + propName, line: node.loc.start.line });
            }
          }
        }
      });
    }

    assert(violations.length === 0, 'Found prohibited runtime globals/APIs: ' + JSON.stringify(violations));
    return { filesChecked: SERVICE_FILES.length, violations: 0 };
  });

  await runTest('S1.4', 'Adversarial Lexical & Token Stream Scan across all service files', function () {
    const prohibitedPatterns = [
      { name: 'Optional Chaining (?.)', regex: /\?\./ },
      { name: 'Nullish Coalescing (??)', regex: /\?\?/ },
      { name: 'Numeric Separator in literals', regex: /\b\d+_\d+\b/ },
      { name: 'BigInt Literal', regex: /\b\d+n\b/ },
      { name: 'Promise.allSettled', regex: /\bPromise\s*\.\s*allSettled\b/ },
      { name: 'Promise.any', regex: /\bPromise\s*\.\s*any\b/ },
      { name: 'Global fetch call', regex: /\bfetch\s*\(/ },
      { name: 'AbortController instantiation', regex: /\bnew\s+AbortController\b/ },
      { name: 'AbortSignal.timeout', regex: /\bAbortSignal\s*\.\s*timeout\b/ },
      { name: 'Readable.fromWeb', regex: /\bReadable\s*\.\s*fromWeb\b/ },
      { name: 'String.prototype.replaceAll', regex: /\.replaceAll\s*\(/ },
      { name: 'Array.prototype.at', regex: /\.at\s*\(\s*-?\d+\s*\)/ }
    ];

    const findings = [];

    for (let f = 0; f < SERVICE_FILES.length; f++) {
      const filename = SERVICE_FILES[f];
      const filePath = path.join(SERVICE_DIR, filename);
      const rawCode = fs.readFileSync(filePath, 'utf8');
      const strippedCode = stripCommentsAndStrings(rawCode);
      const lines = strippedCode.split('\n');

      for (let l = 0; l < lines.length; l++) {
        const line = lines[l];
        for (let p = 0; p < prohibitedPatterns.length; p++) {
          const pat = prohibitedPatterns[p];
          if (pat.regex.test(line)) {
            findings.push({
              file: filename,
              line: l + 1,
              pattern: pat.name,
              snippet: rawCode.split('\n')[l].trim()
            });
          }
        }
      }
    }

    assert(findings.length === 0, 'Lexical scan found prohibited patterns: ' + JSON.stringify(findings, null, 2));
    return { filesScanned: SERVICE_FILES.length, patternsTested: prohibitedPatterns.length, findings: 0 };
  });

  // =========================================================================
  // SUITE 2: ZERO EXTERNAL NPM DEPENDENCIES VERIFICATION
  // =========================================================================
  console.log('\n' + C.bold + C.cyan + '--- SUITE 2: Zero External NPM Dependencies Verification ---' + C.reset);

  await runTest('S2.1', 'Validate package.json strict dependency isolation', function () {
    const pkgPath = path.join(SERVICE_DIR, 'package.json');
    assert(fs.existsSync(pkgPath), 'package.json does not exist');
    const raw = fs.readFileSync(pkgPath, 'utf8');
    const pkg = JSON.parse(raw);

    assert(pkg.name === 'com.cinejoy.tv.service', 'package.json name mismatch: ' + pkg.name);
    assert(pkg.private === true, 'package.json must declare "private": true');
    assert(pkg.dependencies && Object.keys(pkg.dependencies).length === 0, 'package.json dependencies must be empty: ' + JSON.stringify(pkg.dependencies));
    assert(!pkg.devDependencies || Object.keys(pkg.devDependencies).length === 0, 'package.json devDependencies must be empty');
    assert(!pkg.peerDependencies || Object.keys(pkg.peerDependencies).length === 0, 'package.json peerDependencies must be empty');
    assert(!pkg.optionalDependencies || Object.keys(pkg.optionalDependencies).length === 0, 'package.json optionalDependencies must be empty');
    assert(!pkg.bundledDependencies || Object.keys(pkg.bundledDependencies).length === 0, 'package.json bundledDependencies must be empty');

    return {
      name: pkg.name,
      engines: pkg.engines,
      dependenciesCount: 0,
      private: pkg.private
    };
  });

  await runTest('S2.2', 'Verify absence of local node_modules in service directory', function () {
    const nodeModulesPath = path.join(SERVICE_DIR, 'node_modules');
    const exists = fs.existsSync(nodeModulesPath);
    assert(!exists, 'Prohibited node_modules directory found inside ' + SERVICE_DIR);
    return { nodeModulesPresent: false };
  });

  await runTest('S2.3', 'Static Require Analysis: Verify 100% core built-in / local module requires', function () {
    const allowedCoreModules = new Set([
      'http', 'https', 'fs', 'path', 'url', 'crypto', 'stream', 'net',
      'child_process', 'module', 'events', 'util', 'os', 'vm', 'buffer',
      'webos-service' // Allowed target webOS system module
    ]);

    const requiredModulesFound = [];
    const disallowedRequires = [];

    for (let f = 0; f < SERVICE_FILES.length; f++) {
      const filename = SERVICE_FILES[f];
      const filePath = path.join(SERVICE_DIR, filename);
      const rawCode = fs.readFileSync(filePath, 'utf8');
      const stripped = stripCommentsAndStrings(rawCode);

      const requireRegex = /\brequire\s*\(\s*['"]([^'"]+)['"]\s*\)/g;
      let match;
      while ((match = requireRegex.exec(stripped)) !== null) {
        const modName = match[1];
        requiredModulesFound.push({ file: filename, module: modName });

        const isRelative = modName.startsWith('./') || modName.startsWith('../');
        const isAllowedCore = allowedCoreModules.has(modName);

        if (!isRelative && !isAllowedCore) {
          disallowedRequires.push({ file: filename, module: modName });
        }
      }
    }

    assert(disallowedRequires.length === 0, 'Disallowed external requires detected: ' + JSON.stringify(disallowedRequires));
    return {
      totalRequiresChecked: requiredModulesFound.length,
      disallowedRequires: 0,
      modules: Array.from(new Set(requiredModulesFound.map(function (r) { return r.module; })))
    };
  });

  // =========================================================================
  // SUITE 3: LUNA BUS INTERFACE MOCK CHALLENGE
  // =========================================================================
  console.log('\n' + C.bold + C.cyan + '--- SUITE 3: Luna Bus Interface Mock Challenge ---' + C.reset);

  /**
   * High-fidelity WebOS Luna Service Mock conforming to webos-service specification
   */
  function createLunaServiceMock(serviceId) {
    const registeredMethods = {};
    const internalActivities = [];

    const activityManager = {
      exitOnTimeout: true,
      _createInternal: function (activityName, callback) {
        const act = {
          activityId: 'mock_act_' + Math.random().toString(36).substring(2, 9),
          name: activityName,
          state: 'active'
        };
        internalActivities.push(act);
        if (typeof callback === 'function') {
          callback(act);
        }
        return act;
      }
    };

    const mockService = {
      serviceId: serviceId,
      activityManager: activityManager,
      register: function (methodName, requestCallback, cancelCallback) {
        registeredMethods[methodName] = {
          onRequest: requestCallback,
          onCancel: cancelCallback
        };
      },
      // Test harness helpers:
      _registeredMethods: registeredMethods,
      _internalActivities: internalActivities,
      callMethod: function (methodName, messagePayload, options) {
        options = options || {};
        const method = registeredMethods[methodName];
        if (!method) {
          throw new Error('Luna method not registered: ' + methodName);
        }

        const responses = [];
        const uniqueToken = options.uniqueToken || ('tok_' + Math.random().toString(36).substring(2, 9));
        const isSubscription = !!options.subscribe;

        const message = {
          uniqueToken: uniqueToken,
          isSubscription: isSubscription,
          payload: messagePayload,
          respond: function (resp) {
            responses.push(resp);
          }
        };

        method.onRequest(message);

        return {
          message: message,
          responses: responses,
          cancel: function () {
            if (typeof method.onCancel === 'function') {
              method.onCancel(message);
            }
          }
        };
      }
    };

    return mockService;
  }

  // Intercept 'webos-service' via Module.prototype.require
  const origRequire = Module.prototype.require;
  const mockLunaService = createLunaServiceMock('com.cinejoy.tv.service');

  let serviceInstance = null;

  Module.prototype.require = function (id) {
    if (id === 'webos-service') {
      return function MockServiceConstructor(name) {
        return mockLunaService;
      };
    }
    return origRequire.apply(this, arguments);
  };

  try {
    // Require index.js which initializes startServer and initWebosService
    serviceInstance = require(path.join(SERVICE_DIR, 'index.js'));
  } catch (err) {
    console.error('Failed to load service index.js:', err);
  }

  // Helper: wait until Luna methods are registered
  async function waitForLunaRegistration(maxWaitMs) {
    const start = Date.now();
    while (Date.now() - start < maxWaitMs) {
      if (mockLunaService._registeredMethods && mockLunaService._registeredMethods.keepalive) {
        return true;
      }
      await new Promise(function (r) { setTimeout(r, 20); });
    }
    return false;
  }

  await runTest('S3.1', 'Triple-Shield Persistence & Luna method registration audit', async function () {
    const ready = await waitForLunaRegistration(4000);
    assert(ready, 'Timeout waiting for initWebosService() registration');

    // Verify Shield 1: exitOnTimeout is disabled
    assert(mockLunaService.activityManager.exitOnTimeout === false, 'Shield 1 FAILED: exitOnTimeout was not set to false');

    // Verify Shield 2: Internal keepalive activity created
    assert(mockLunaService._internalActivities.length >= 1, 'Shield 2 FAILED: No internal keepalive activity created');
    assert(mockLunaService._internalActivities[0].name === 'cinejoy_proxy_keepalive', 'Shield 2 FAILED: Expected cinejoy_proxy_keepalive activity, got: ' + mockLunaService._internalActivities[0].name);

    // Verify Shield 3: All 4 Luna methods registered
    const expectedMethods = ['keepalive', 'status', 'health', 'ping'];
    for (let m = 0; m < expectedMethods.length; m++) {
      const name = expectedMethods[m];
      assert(mockLunaService._registeredMethods[name], 'Missing Luna method registration: ' + name);
      assert(typeof mockLunaService._registeredMethods[name].onRequest === 'function', 'Method ' + name + ' has no request callback');
    }

    assert(typeof mockLunaService._registeredMethods.keepalive.onCancel === 'function', 'Method keepalive missing onCancel callback');

    return {
      shield1_exitOnTimeout: mockLunaService.activityManager.exitOnTimeout,
      shield2_internalActivity: mockLunaService._internalActivities[0].name,
      registeredMethods: Object.keys(mockLunaService._registeredMethods)
    };
  });

  await runTest('S3.2', 'Luna keepalive single subscription registration', function () {
    const callResult = mockLunaService.callMethod('keepalive', {}, { subscribe: true, uniqueToken: 'client_session_1' });
    assert(callResult.responses.length === 1, 'Expected 1 response, got ' + callResult.responses.length);
    const resp = callResult.responses[0];

    assert(resp.returnValue === true, 'Expected returnValue: true');
    assert(resp.status === 'subscribed', 'Expected status: "subscribed", got: ' + resp.status);
    assert(typeof resp.port === 'number' && resp.port >= 8088, 'Expected valid port, got: ' + resp.port);
    assert(typeof resp.uptime === 'number' && resp.uptime >= 0, 'Expected numeric uptime');

    return { response: resp, token: 'client_session_1' };
  });

  await runTest('S3.3', 'Luna keepalive multiple concurrent subscribers', function () {
    const tokens = ['client_sub_A', 'client_sub_B', 'client_sub_C', 'client_sub_D'];
    const subscribers = [];

    for (let i = 0; i < tokens.length; i++) {
      const token = tokens[i];
      const res = mockLunaService.callMethod('keepalive', {}, { subscribe: true, uniqueToken: token });
      assert(res.responses.length === 1, 'Subscriber ' + token + ' failed response');
      assert(res.responses[0].status === 'subscribed', 'Subscriber ' + token + ' expected subscribed');
      subscribers.push(res);
    }

    return { concurrentSubscribersCreated: tokens.length };
  });

  await runTest('S3.4', 'Luna keepalive subscription cancellation & selective removal', function () {
    // Subscribe client 10 and client 20
    const sub10 = mockLunaService.callMethod('keepalive', {}, { subscribe: true, uniqueToken: 'tok_to_cancel_10' });
    const sub20 = mockLunaService.callMethod('keepalive', {}, { subscribe: true, uniqueToken: 'tok_to_retain_20' });

    assert(sub10.responses[0].status === 'subscribed', 'sub10 failed to subscribe');
    assert(sub20.responses[0].status === 'subscribed', 'sub20 failed to subscribe');

    // Cancel sub10
    sub10.cancel();

    // Challenge: cancel again (double cancellation resilience)
    sub10.cancel();

    // Challenge: cancel non-existent token
    const ghostMessage = { uniqueToken: 'ghost_token_never_subscribed' };
    mockLunaService._registeredMethods.keepalive.onCancel(ghostMessage);

    return { canceledToken: 'tok_to_cancel_10', retainedToken: 'tok_to_retain_20', doubleCancelSafe: true };
  });

  await runTest('S3.5', 'Luna keepalive one-shot request (non-subscription)', function () {
    const res = mockLunaService.callMethod('keepalive', {}, { subscribe: false, uniqueToken: 'oneshot_query' });
    assert(res.responses.length === 1, 'Expected 1 response');
    const resp = res.responses[0];

    assert(resp.returnValue === true, 'Expected returnValue: true');
    assert(resp.status === 'running', 'Expected status: "running" for non-subscription, got: ' + resp.status);
    assert(typeof resp.port === 'number', 'Expected numeric port');

    return { response: resp };
  });

  await runTest('S3.6', 'Luna status method reporting & schema validation', function () {
    const res = mockLunaService.callMethod('status', {});
    assert(res.responses.length === 1, 'Expected 1 response');
    const resp = res.responses[0];

    assert(resp.returnValue === true, 'status.returnValue must be true');
    assert(resp.status === 'running', 'status.status must be "running"');
    assert(resp.serviceId === 'com.cinejoy.tv.service', 'status.serviceId mismatch: ' + resp.serviceId);
    assert(typeof resp.port === 'number' && resp.port >= 8088, 'status.port must be valid integer');
    assert(typeof resp.uptime === 'number', 'status.uptime must be number');
    assert(typeof resp.rssBytes === 'number' && resp.rssBytes > 0, 'status.rssBytes must be positive integer');

    return { statusResponse: resp };
  });

  await runTest('S3.7', 'Luna health method reporting & schema validation', function () {
    const res = mockLunaService.callMethod('health', {});
    assert(res.responses.length === 1, 'Expected 1 response');
    const resp = res.responses[0];

    assert(resp.returnValue === true, 'health.returnValue must be true');
    assert(resp.status === 'ok', 'health.status must be "ok"');
    assert(resp.mode === 'on-device-service', 'health.mode must be "on-device-service"');
    assert(resp.serviceId === 'com.cinejoy.tv.service', 'health.serviceId mismatch: ' + resp.serviceId);
    assert(typeof resp.memory === 'object' && resp.memory.rss > 0, 'health.memory must contain valid memory stats');

    return { healthResponse: resp };
  });

  await runTest('S3.8', 'Luna ping method backward compatibility', function () {
    const res = mockLunaService.callMethod('ping', {});
    assert(res.responses.length === 1, 'Expected 1 response');
    const resp = res.responses[0];

    assert(resp.returnValue === true, 'ping.returnValue must be true');
    assert(resp.pong === true, 'ping.pong must be true');
    assert(typeof resp.time === 'number' && resp.time > 0, 'ping.time must be timestamp');
    assert(resp.serviceId === 'com.cinejoy.tv.service', 'ping.serviceId mismatch');

    return { pingResponse: resp };
  });

  await runTest('S3.9', 'Luna interface resilience when activityManager is undefined/stripped', function () {
    const strippedMockService = createLunaServiceMock('com.cinejoy.tv.service');
    delete strippedMockService.activityManager;

    let crashed = false;
    try {
      if (strippedMockService.activityManager) {
        strippedMockService.activityManager.exitOnTimeout = false;
      }
      strippedMockService.register('keepalive', function (m) { m.respond({ returnValue: true }); });
    } catch (_) {
      crashed = true;
    }
    assert(!crashed, 'Failed graceful degradation when activityManager is missing');

    return { survivedActivityManagerAbsence: true };
