/**
 * Strip only comments while preserving string literals
 */
function stripOnlyComments(src) {
  let out = '';
  let i = 0;
  const len = src.length;
  while (i < len) {
    if (src[i] === '/' && src[i + 1] === '/') {
      i += 2;
      out += '  ';
      while (i < len && src[i] !== '\n') {
        out += ' ';
        i++;
      }
    } else if (src[i] === '/' && src[i + 1] === '*') {
      i += 2;
      out += '  ';
      while (i < len && !(src[i] === '*' && src[i + 1] === '/')) {
        if (src[i] === '\n') out += '\n';
        else out += ' ';
        i++;
      }
      if (i < len) {
        i += 2;
        out += '  ';
      }
    } else if (src[i] === '"' || src[i] === "'" || src[i] === '`') {
      const q = src[i++];
      out += q;
      while (i < len && src[i] !== q) {
        if (src[i] === '\\') {
          out += src[i] + src[i + 1];
          i += 2;
          continue;
        }
        out += src[i++];
      }
      if (i < len) {
        out += src[i++];
      }
    } else {
      out += src[i++];
    }
  }
  return out;
}

